kernels/psf_splat.cl.body:
/* =========================================================================
 * psf_splat.cl  --  PSF v2 surface evaluation + sub-pixel splat renderer
 * Hand-written, dependency-free OpenCL C 1.2. No SDK helpers, no libs.
 *
 * PIPELINE (one dispatch per frame):
 *   clear_fb   : reset packed depth|color buffer to "far, black"
 *   psf_splat  : sample -> evaluate surface equations -> project -> splat
 *   resolve_fb : unpack winning color per pixel into RGBA8 image
 *
 * WHY THIS IS CHEAP ON THE SAME BASE CIRCUITRY:
 *   Every sample is a straight FMA chain: bilinear lerps (position and
 *   normal), the 8-term corner-vanishing polynomial, 4 stitch terms,
 *   pattern color dot products, one 4x4 matrix multiply. No texture
 *   units, no special-function units in the hot path (cospi only in
 *   color patterns), no divergent loops: every thread runs the same
 *   instruction stream. Reads are 64-byte records reused by thousands
 *   of samples (cache-resident); the only scatter is ONE 64-bit atomic
 *   per sample. ~115 FLOPs/sample -> ~36 GFLOP/s at 1080p60 with
 *   2.5 samples/px: about 1.3% of a GTX 1650.
 *
 * DEPTH-TESTED SPLAT WITHOUT A RASTERIZER:
 *   key = (depth_bits << 32) | RGBA8. atom_min keeps the nearest sample
 *   and its color in ONE atomic op. float32 depth bits are monotonic
 *   for depth >= 0, so integer min == nearest. Needs
 *   cl_khr_int64_extended_atomics (define USE_LONG_ATOMICS).
 *   Fallback for ancient GPUs (no 64-bit atomics): two-pass version,
 *   atomic_min on a uint depth buffer, then a color pass that writes
 *   only where its depth won (benign race: equal depth = same surface).
 *
 * RECORD LAYOUTS (byte offsets inside each 64-byte record; matches the
 * Python encoder psf_v2_quadtree.py byte-for-byte):
 *   AnchorPointBuffer:
 *     32: ushort pos[3]   (quantized over bbox)
 *     44: uchar  normal[3] (n*0.5+0.5 quantized)   <- displacement dir
 *     16: uchar  curve_params[16]                  <- stitch coefs home
 *   ProceduralSurfaceBuffer:
 *      0: ushort anchor_idx[4]
 *     12: float  coef[8]      corner-vanishing deformation basis
 *     44: 3 x { uchar idx_hi4|lo4, uchar idx_hi4|lo4, char K[4] }
 *         color = sum_i (K_i/63) * Pattern_{idx_i}(u,v)  per channel
 * ========================================================================= */

#ifdef USE_LONG_ATOMICS
#pragma OPENCL EXTENSION cl_khr_int64_base_atomics : enable
#pragma OPENCL EXTENSION cl_khr_int64_extended_atomics : enable
#endif

/* ---------- record accessors (pure pointer math, no structs: immune to
 *            host/device struct-packing disagreements) ------------------ */

inline float3 anchor_pos(__global const uchar *A, uint i,
                         float3 bbmin, float3 bbspan)
{
    __global const ushort *q = (__global const ushort *)(A + i*64u + 32u);
    return bbmin + bbspan * (float3)(q[0], q[1], q[2]) * (1.0f/65535.0f);
}

inline float3 anchor_nrm(__global const uchar *A, uint i)
{
    __global const uchar *n = A + i*64u + 44u;
    return fast_normalize((float3)(n[0], n[1], n[2]) * (2.0f/255.0f)
                          - (float3)(1.0f, 1.0f, 1.0f));
}

/* ---------- the predetermined equations ------------------------------- */

/* corner-vanishing, edge-separable deformation basis.
 * h == 0 at all four corners  -> surface interpolates its anchors
 * each edge owned by exactly 2 coefs -> sewing = adjust 2 numbers   */
inline float deform_h(const float c[8], float u, float v)
{
    float bu = u * (1.0f - u), bv = v * (1.0f - v);
    float au = 2.0f*u - 1.0f,  av = 2.0f*v - 1.0f;
    float w  = 1.0f - v,       x  = 1.0f - u;
    return fma(c[0], bu*w,  fma(c[1], bu*v,
           fma(c[2], bv*x,  fma(c[3], bv*u,
           fma(c[4], bu*au*w, fma(c[5], bu*au*v,
           fma(c[6], bv*av*x,     c[7]*bv*av*u)))))));
}

/* analytic partials of deform_h (matches Patch::HeightGrad on the host).
 * Used for the TRUE surface normal so shading is the geometric normal of
 * the DEFORMED surface, not the base displacement direction Nd. */
inline void deform_dh(const float c[8], float u, float v,
                      float *dhu, float *dhv)
{
    float bu = u*(1.0f-u), bv = v*(1.0f-v);
    float au = 2.0f*u-1.0f, av = 2.0f*v-1.0f;
    float w = 1.0f-v, x = 1.0f-u;
    float dbu = 1.0f-2.0f*u, dbv = 1.0f-2.0f*v;
    float dcu = dbu*au + 2.0f*bu;          /* d(bu*au)/du */
    float dcv = dbv*av + 2.0f*bv;          /* d(bv*av)/dv */
    *dhu = c[0]*dbu*w + c[1]*dbu*v - c[2]*bv + c[3]*bv
         + c[4]*dcu*w + c[5]*dcu*v - c[6]*bv*av + c[7]*bv*av;
    *dhv = -c[0]*bu + c[1]*bu + c[2]*dbv*x + c[3]*dbv*u
         - c[4]*bu*au + c[5]*bu*au + c[6]*dcv*x + c[7]*dcv*u;
}

/* stitch ("sewing"): s(t) = t(1-t)(a + b t), per edge, int8-quantized.
 * weights (1-v), v, (1-u), u blend each edge correction inward.
 * Lives in anchor curve_params in the full format; passed as its own
 * buffer here for clarity. Physics can rewrite 2 bytes per edge to
 * deform BOTH neighbors crack-free. */
inline float stitch_h(__global const char *S, uint surf, float u, float v,
                      float s_scale)
{
    __global const char *e = S + surf * 8u;           /* 4 edges x (a,b) */
    float s = 0.0f;
    float tu = u*(1.0f-u), tv = v*(1.0f-v);
    s += (1.0f-v) * tu * (e[0]*s_scale + e[1]*s_scale*u);   /* edge v=0 */
    s +=        v * tu * (e[2]*s_scale + e[3]*s_scale*u);   /* edge v=1 */
    s += (1.0f-u) * tv * (e[4]*s_scale + e[5]*s_scale*v);   /* edge u=0 */
    s +=        u * tv * (e[6]*s_scale + e[7]*s_scale*v);   /* edge u=1 */
    return s;
}

/* presaved pattern library (engine-side; files store only indices + K) */
inline float pattern_eval(uint idx, float u, float v)
{
    switch (idx & 15u) {
        case 0:  return 1.0f;
        case 1:  return u;
        case 2:  return v;
        case 3:  return u*v;
        case 4:  return u*u;
        case 5:  return v*v;
        case 6:  return u*u*v;
        case 7:  return u*v*v;
        case 8:  return cospi(u);
        case 9:  return cospi(v);
        case 10: return cospi(2.0f*u);
        case 11: return cospi(2.0f*v);
        case 12: return cospi(u)*cospi(v);
        case 13: return cospi(2.0f*u)*cospi(2.0f*v);
        case 14: return cospi(3.0f*u);
        default: return cospi(3.0f*v);
    }
}

inline float channel_color(__global const uchar *srec, uint ch,
                           float u, float v)
{
    __global const uchar *c = srec + 44u + ch*6u;
    uint i0 = c[0] >> 4, i1 = c[0] & 15u, i2 = c[1] >> 4, i3 = c[1] & 15u;
    __global const char *K = (__global const char *)(c + 2);
    float r = (K[0]*(1.0f/63.0f)) * pattern_eval(i0, u, v);
    r = fma((float)K[1]*(1.0f/63.0f), pattern_eval(i1, u, v), r);
    r = fma((float)K[2]*(1.0f/63.0f), pattern_eval(i2, u, v), r);
    r = fma((float)K[3]*(1.0f/63.0f), pattern_eval(i3, u, v), r);
    return clamp(r, 0.0f, 1.0f);
}

/* ---------- kernels ---------------------------------------------------- */

__kernel void clear_fb(__global ulong *fb, uint n)
{
    uint g = get_global_id(0);
    if (g < n) fb[g] = 0xFFFFFFFFFFFFFFFFUL;   /* depth=+inf-ish, color=0 */
}

/* one work-item = one surface sample.
 * sample_off : prefix sums, surface s owns gids [off[s], off[s+1])
 * sample_ss  : per-surface grid side (adaptive: from projected size)   */
__kernel void psf_splat(
    __global const uchar  *anchors,
    __global const float4 *snorm,         /* smooth per-anchor shading normal */
    __global const uchar  *surfaces,
    __global const char   *stitch,        /* 8 int8 per surface */
    __global const uint   *sample_off,
    __global const uint   *sample_ss,    /* (ss_u << 16) | ss_v, per surface */
    const uint  n_surfaces,
    const float3 bbmin, const float3 bbspan,
    const float  s_scale,                  /* stitch dequant scale */
    const float16 mvp,                     /* row-major */
    const float3 light_dir,
    const float3 eye,                      /* camera position (world) */
    const uint  width, const uint height,
    __global volatile ulong *fb
#ifndef USE_LONG_ATOMICS
    , __global volatile uint *depth32     /* fallback path, pass 1 use */
    , const uint pass                     /* 0 = depth, 1 = color */
#endif
)
{
    uint gid = get_global_id(0);
    if (gid >= sample_off[n_surfaces]) return;

    /* binary search: which surface owns this sample id */
    uint lo = 0, hi = n_surfaces;
    while (hi - lo > 1u) {
        uint mid = (lo + hi) >> 1;
        if (sample_off[mid] <= gid) lo = mid; else hi = mid;
    }
    const uint s    = lo;
    const uint k    = gid - sample_off[s];
    const uint ssu  = sample_ss[s] >> 16;          /* anisotropic grid:   */
    const uint ssv  = sample_ss[s] & 0xFFFFu;      /* per-axis density    */
    const float u = (float)(k % ssu) / (float)(ssu - 1u);
    const float v = (float)(k / ssu) / (float)(ssv - 1u);

    __global const uchar *srec = surfaces + s*64u;
    __global const ushort *aidx = (__global const ushort *)srec;

    /* anchors: positions + displacement-direction normals */
    float3 A0 = anchor_pos(anchors, aidx[0], bbmin, bbspan);
    float3 A1 = anchor_pos(anchors, aidx[1], bbmin, bbspan);
    float3 A2 = anchor_pos(anchors, aidx[2], bbmin, bbspan);
    float3 A3 = anchor_pos(anchors, aidx[3], bbmin, bbspan);
    float3 N0 = anchor_nrm(anchors, aidx[0]);
    float3 N1 = anchor_nrm(anchors, aidx[1]);
    float3 N2 = anchor_nrm(anchors, aidx[2]);
    float3 N3 = anchor_nrm(anchors, aidx[3]);

    /* bilinear base (uu along A0->A3 edge, vv along A0->A1 edge) */
    float3 pl = mix(A0, A3, u), pr = mix(A1, A2, u);
    float3 P  = mix(pl, pr, v);
    float3 nl = mix(N0, N3, u), nr = mix(N1, N2, u);
    float3 Nd = fast_normalize(mix(nl, nr, v));

    /* deformation + sewing along the SHARED normal field */
    float c[8];
    {   __global const float *cf = (__global const float *)(srec + 12u);
        for (int i = 0; i < 8; ++i) c[i] = cf[i];
    }
    float h = deform_h(c, u, v) + stitch_h(stitch, s, u, v, s_scale);
    P = fma((float3)(h, h, h), Nd, P);

    /* SMOOTH SHADING NORMAL ("check there once"): the host precomputes one
     * true geometric normal per anchor (PSFBody::ComputeSmoothNormals) --
     * averaged over every patch sharing the anchor -- in the parallel
     * `snorm` buffer (kept separate from the anchor record's normal slot,
     * which is the displacement direction Nd and differs by up to 90 deg).
     * Interpolating these 4 corner normals gives a C0-continuous geometric
     * normal across patch borders: no facets, no per-sample cross product,
     * no shading streaks. */
    float3 S0 = snorm[aidx[0]].xyz, S1 = snorm[aidx[1]].xyz;
    float3 S2 = snorm[aidx[2]].xyz, S3 = snorm[aidx[3]].xyz;
    float3 snl = mix(S0, S3, u), snr = mix(S1, S2, u);
    float3 Nshade = fast_normalize(mix(snl, snr, v));

    /* BACK-FACE CULL ("skip patches that shouldn't draw"): if this point's
     * geometric normal faces away from the camera, it's on the far side of
     * the object and must not be splatted -- otherwise back samples bleed
     * through the front wherever the z-buffer doesn't perfectly occlude
     * them (the tearing on the away-facing side). view = P - eye; a point
     * is back-facing when dot(N, view) > 0 (normal points downstream of the
     * view ray). A small bias keeps silhouette samples that are nearly
     * edge-on. */
    float3 view = fast_normalize(P - eye);
    if (dot(Nshade, view) > 0.10f) return;

    /* project */
    float4 hp = (float4)(
        dot(mvp.s0123, (float4)(P, 1.0f)),
        dot(mvp.s4567, (float4)(P, 1.0f)),
        dot(mvp.s89ab, (float4)(P, 1.0f)),
        dot(mvp.scdef, (float4)(P, 1.0f)));
    if (hp.w <= 1e-6f) return;
    float2 ndc = hp.xy / hp.w;
    if (fabs(ndc.x) > 1.0f || fabs(ndc.y) > 1.0f) return;
    uint px = (uint)((ndc.x * 0.5f + 0.5f) * (float)(width  - 1u) + 0.5f);
    uint py = (uint)((0.5f - ndc.y * 0.5f) * (float)(height - 1u) + 0.5f);
    uint pix = py * width + px;
    float depth = hp.

kernels/spf_splat.cl.body:
/* =========================================================================
 * spf_splat.cl  --  Spectral-primitive renderer. "Complex models from
 * simple equations": the whole object is a sphere primitive (center +
 * base radius) plus a baked detail field expressed as a real spherical-
 * harmonic expansion. NO anchors, NO patches, NO seams -- a single
 * continuous field. Each work-item marches ONE direction (theta,phi),
 * evaluates the field in registers, projects, and splats with the same
 * 64-bit atom_min depth trick as psf_splat.cl.
 *
 * WHY THIS IS CHEAP ON THE SAME BASE CIRCUITRY:
 *   Each thread evaluates the SH field as an FMA chain over (L+1)^2 terms
 *   using the stable associated-Legendre recurrence -- no special-function
 *   units except sin/cos for the direction and the azimuth harmonics. The
 *   coefficient arrays are tiny (geom (L+1)^2 floats, color 3*(Lc+1)^2)
 *   and stay cache-resident, read by every thread. The only scatter is one
 *   64-bit atomic per sample. No divergent loops: every thread runs the
 *   same term count. There is no back-face problem to cull and no seam to
 *   stitch, so the inner loop is pure arithmetic.
 *
 * SH CONVENTION: real spherical harmonics matching the Python baker
 *   (scipy sph_harm_y, real form, with the extra (-1)^m the baker applies).
 *   Y_l^0  = K_l^0 * P_l^0(cos t)
 *   Y_l^m  = sqrt2 * K_l^m * P_l^m(cos t) * cos(m phi)   (m>0)
 *   Y_l^-m = sqrt2 * K_l^m * P_l^m(cos t) * sin(m phi)   (m>0)
 *   with an extra sign (-1)^m folded in for odd m to match the baker, and
 *   K_l^m = sqrt((2l+1)/(4pi) * (l-m)!/(l+m)!).
 * ========================================================================= */

#define PI_F 3.14159265358979323846f

/* Fully-normalized associated Legendre via the stable column recurrence.
 * Computes Nlm = K_l^m * P_l^m(x) directly (normalization folded in), so no
 * intermediate factorial or P_m^m ever overflows float32 -- valid to high
 * order. Fills nrm[l] for the requested m (l from m..L). Standard geodesy
 * recurrence (e.g. Holmes & Featherstone), Condon-Shortley folded out here
 * and re-applied to match the baker sign in sh_field. */
static float norm_plm_seed(int m, float x) {
    /* N_m^m = sqrt((2m+1)/(4pi) * prod_{k=1..m} (2k-1)/(2k)) * (sin t)^m
     * built incrementally to stay in range. sin t = sqrt(1-x^2). */
    float sint = sqrt(fmax(0.0f, 1.0f - x * x));
    float val = sqrt(1.0f / (4.0f * PI_F));      /* N_0^0 */
    for (int k = 1; k <= m; ++k)
        val *= sqrt((2.0f * k + 1.0f) / (2.0f * k)) * sint;
    return val;   /* = N_m^m, includes (sin t)^m, no overflow */
}

static float sh_field(__global const float* coef, int L, float x,
                      float phi) {
    float sint = sqrt(fmax(0.0f, 1.0f - x * x));
    /* precompute cos(m phi), sin(m phi) incrementally */
    float s = 0.0f;
    int idx_base = 0;   /* index of (l=0,m=0) growing per l handled below */
    /* We iterate m outer (columns), l inner, but coef index is l-major
     * (l, m=-l..l). Easiest: recompute linear index from (l,m). */
    for (int m = 0; m <= L; ++m) {
        float cmp = cos((float)m * phi);
        float smp = sin((float)m * phi);
        /* seed N_m^m and N_{m+1}^m for the column recurrence */
        float nmm = norm_plm_seed(m, x);
        float prev = 0.0f;        /* N_{m-1}^m = 0 */
        float cur = nmm;          /* N_m^m */
        for (int l = m; l <= L; ++l) {
            float nlm;
            if (l == m) nlm = cur;
            else {
                /* normalized recurrence:
                 * N_l^m = a*(x*N_{l-1}^m) - b*N_{l-2}^m
                 * a = sqrt((2l-1)(2l+1)/((l-m)(l+m)))
                 * b = sqrt((2l+1)(l+m-1)(l-m-1)/((l-m)(l+m)(2l-3))) */
                float a = sqrt(((2.0f*l-1.0f)*(2.0f*l+1.0f)) /
                               ((l - m) * (l + m)));
                float b = sqrt(((2.0f*l+1.0f)*(l+m-1.0f)*(l-m-1.0f)) /
                               ((l - m) * (l + m) * (2.0f*l-3.0f)));
                nlm = a * x * cur - b * prev;
                prev = cur; cur = nlm;
            }
            /* coef linear index for (l,m) and (l,-m) in l-major layout */
            int row = l * l + l;     /* index of (l, 0) */
            if (m == 0) {
                s += nlm * coef[row];
            } else {
                /* the normalized seed already carries the correct sign;
                 * no extra (-1)^m needed (verified against the baker). */
                float y_pos = 1.41421356f * nlm * cmp; /* (l, +m) */
                float y_neg = 1.41421356f * nlm * smp; /* (l, -m) */
                s += y_pos * coef[row + m];
                s += y_neg * coef[row - m];
            }
        }
    }
    return s;
}

/* clear packed framebuffer */
__kernel void clear_fb(__global ulong* fb, const uint n) {
    uint i = get_global_id(0);
    if (i < n) fb[i] = 0xFFFFFFFFFFFFFFFFUL;
}

/* Continuous-order field eval (the user's model: the image is a continuous
 * combination of frequency bands that appear GRADUALLY with proximity). Lc
 * is a float: bands with l <= floor(Lc) contribute fully, band
 * l == floor(Lc)+1 is weighted by frac(Lc), higher bands are 0. So as the
 * camera nears and Lc rises smoothly, each frequency fades in -- no popping,
 * unlike integer truncation which switches a whole band on at once. */
static float sh_field_lod(__global const float* coef, float Lc, int Lmax,
                          float x, float phi) {
    float sint = sqrt(fmax(0.0f, 1.0f - x * x));
    int Lint = (int)floor(Lc);
    float frac = Lc - (float)Lint;
    int Ltop = Lint + 1;                 /* highest band that contributes */
    if (Ltop > Lmax) { Ltop = Lmax; Lint = Lmax; frac = 0.0f; }  /* never read past buffer */
    float s = 0.0f;
    for (int m = 0; m <= Ltop; ++m) {
        float cmp = cos((float)m * phi);
        float smp = sin((float)m * phi);
        float prev = 0.0f;
        float cur = norm_plm_seed(m, x);
        for (int l = m; l <= Ltop; ++l) {
            float nlm;
            if (l == m) nlm = cur;
            else {
                float a = sqrt(((2.0f*l-1.0f)*(2.0f*l+1.0f)) /
                               ((l - m) * (l + m)));
                float b = sqrt(((2.0f*l+1.0f)*(l+m-1.0f)*(l-m-1.0f)) /
                               ((l - m) * (l + m) * (2.0f*l-3.0f)));
                nlm = a * x * cur - b * prev;
                prev = cur; cur = nlm;
            }
            /* per-band weight: full up to Lint, fractional at Lint+1 */
            float w = (l <= Lint) ? 1.0f : frac;
            if (w == 0.0f) continue;
            int row = l * l + l;
            if (m == 0) {
                s += w * nlm * coef[row];
            } else {
                s += w * 1.41421356f * nlm * cmp * coef[row + m];
                s += w * 1.41421356f * nlm * smp * coef[row - m];
            }
        }
    }
    return s;
}


__kernel void spf_splat(
    __global const float* gcoef,   /* geom field, (Lg+1)^2 */
    __global const float* ccoef,   /* color field, 3*(Lc+1)^2 (ch-major) */
    const int   Lg, const float Lc, const int Lc_stored,
    const float3 center, const float base_r,
    const uint  n_samples,         /* total directions (Fibonacci sphere) */
    const uint  pad_unused,        /* kept for arg-count stability */
    const float16 mvp,             /* row-major */
    const float3 light_dir,
    const float3 eye,
    const uint  width, const uint height,
    __global volatile ulong* fb)
{
    uint gid = get_global_id(0);
    if (gid >= n_samples) return;

    /* Fibonacci-sphere direction: uniform area density, no pole clustering
     * (the (theta,phi) grid amassed samples at the poles and left thin gaps
     * elsewhere -> faint lines). z is evenly spaced in [-1,1]; the azimuth
     * advances by the golden angle, so points spiral evenly over the sphere. */
    const float GA = 2.39996322972865332f;          /* golden angle */
    float zc = 1.0f - 2.0f * (gid + 0.5f) / (float)n_samples;  /* cos(theta) */
    float rxy = sqrt(fmax(0.0f, 1.0f - zc * zc));
    float az = GA * (float)gid;
    float theta = acos(zc);
    float phi = az - 2.0f * PI_F * floor((az + PI_F) / (2.0f * PI_F)); /* wrap to [-pi,pi) */
    float ct = zc, st = rxy;

    /* field radius + position */
    float R = base_r + sh_field(gcoef, Lg, ct, phi);
    float3 dir = (float3)(st * cos(phi), st * sin(phi), ct);
    float3 P = center + dir * R;

    /* analytic-ish normal via finite diff of the field in theta/phi */
    float e = 1e-3f;
    float ct2 = cos(theta + e), st2 = sin(theta + e);
    float R2 = base_r + sh_field(gcoef, Lg, ct2, phi);
    float3 Pt = center + (float3)(st2*cos(phi), st2*sin(phi), ct2) * R2;
    float Rp = base_r + sh_field(gcoef, Lg, ct, phi + e);
    float3 Pp = center + (float3)(st*cos(phi+e), st*sin(phi+e), ct) * Rp;
    float3 nrm = normalize(cross(Pt - P, Pp - P));
    if (dot(nrm, dir) < 0.0f) nrm = -nrm;

    /* project */
    float4 hp;
    hp.x = mvp.s0*P.x + mvp.s1*P.y + mvp.s2*P.z + mvp.s3;
    hp.y = mvp.s4*P.x + mvp.s5*P.y + mvp.s6*P.z + mvp.s7;
    hp.z = mvp.s8*P.x + mvp.s9*P.y + mvp.sa*P.z + mvp.sb;
    hp.w = mvp.sc*P.x + mvp.sd*P.y + mvp.se*P.z + mvp.sf;
    if (hp.w <= 1e-6f) return;
    float3 ndc = hp.xyz / hp.w;
    if (fabs(ndc.x) > 1.0f || fabs(ndc.y) > 1.0f) return;
    float depth = ndc.z;
    if (depth < 0.0f) return;

    int px = (int)((ndc.x * 0.5f + 0.5f) * (width  - 1) + 0.5f);
    int py = (int)((0.5f - ndc.y * 0.5f) * (height - 1) + 0.5f);
    if (px < 0 || px >= (int)width || py < 0 || py >= (int)height) return;

    /* color field + lambert. Lc_stored is how many coefs are stored per
     * channel (the stride); Lc is the LOD order to actually sum (<= stored).
     * Summing fewer orders = the inherent texture LOD: soft when far. */
    int nc = (Lc_stored + 1) * (Lc_stored + 1);
    float cr = sh_field_lod(ccoef,          Lc, Lc_stored, ct, phi);
    float cg = sh_field_lod(ccoef + nc,     Lc, Lc_stored, ct, phi);
    float cb = sh_field_lod(ccoef + 2 * nc, Lc, Lc_stored, ct, phi);
    float lam = fmax(dot(nrm, -light_dir), 0.0f) * 0.85f + 0.15f;
    uint r = (uint)(clamp(cr * lam, 0.0f, 1.0f) * 255.0f);
    uint g = (uint)(clamp(cg * lam, 0.0f, 1.0f) * 255.0f);
    uint b = (uint)(clamp(cb * lam, 0.0f, 1.0f) * 255.0f);
    uint rgba = (r << 24) | (g << 16) | (b << 8) | 0xFF;

    /* depth-tested splat: key = (depth_bits << 32) | rgba, atom_min */
    uint dbits = as_uint(depth);
    ulong key = ((ulong)dbits << 32) | (ulong)rgba;
    atom_min(&fb[py * width + px], key);
}

/* resolve packed fb -> RGBA8 image */
__kernel void resolve_fb(__global const ulong* fb, __global uchar4* img,
                         const uint n) {
    uint i = get_global_id(0);
    if (i >= n) return;
    ulong key = fb[i];
    if (key == 0xFFFFFFFFFFFFFFFFUL) { img[i] = (uchar4)(18,18,24,255); return; }
    uint rgba = (uint)(key & 0xFFFFFFFFUL);
    img[i] = (uchar4)((rgba>>24)&0xFF, (rgba>>16)&0xFF, (rgba>>8)&0xFF, 0xFF);
}

kernels/surfel_inverse.cl.body:
// =============================================================================
// surfel_inverse.cl - INVERSE (per-pixel) rasterization for DeliRium.
//
// What the user actually asked for: instead of splatting each surfel as a disc
// onto the screen (forward), we treat EACH PIXEL of the screen as the unit of
// work. One thread per pixel. The pixel "asks the model" what surface is there
// by finding the nearest projected surface sample along its ray. No discs, no
// giant points -- resolution is exactly the screen (W x H). A final pass fills
// genuine holes (pixels that found nothing but sit inside the silhouette) by
// averaging neighbors.
//
// To keep the per-pixel query cheap, surfels are first binned into a screen
// grid (bin_kernel); each pixel then only inspects its own bin + 8 neighbors
// instead of all surfels.
// =============================================================================

typedef struct {
    float px, py, pz;
    float nx, ny, nz;
    float r,  g,  b;
    float radius;
} Surfel;

// project a surfel to screen; returns 0 if behind camera
static int project(const Surfel* s, float3 eye, float3 fwd, float3 right,
                   float3 up, float focal, int W, int H,
                   float* outx, float* outy, float* outz) {
    float3 pos = (float3)(s->px, s->py, s->pz);
    float3 rel = pos - eye;
    float z = dot(rel, fwd);
    if (z < 1e-3f) return 0;
    *outx = dot(rel, right) / z * focal + W * 0.5f;
    *outy = H * 0.5f - dot(rel, up) / z * focal;
    *outz = z;
    return 1;
}

// Pass 1: bin each surfel into the screen cell it projects to. We store, per
// cell, the nearest-depth surfel index (atomic min on a packed depth|index).
__kernel void bin_surfels(
    __global const Surfel* surfels, const uint n_surfels,
    __global ulong* cell,            // packed (depthbits<<32 | index), per cell
    const uint gw, const uint gh, const uint cellpx,
    const float3 eye, const float3 fwd, const float3 right, const float3 up,
    const float focal, const uint W, const uint H)
{
    uint i = get_global_id(0);
    if (i >= n_surfels) return;
    float sx, sy, sz;
    if (!project(&surfels[i], eye, fwd, right, up, focal, W, H, &sx, &sy, &sz))
        return;
    int cxp = (int)(sx / cellpx), cyp = (int)(sy / cellpx);
    if (cxp < 0 || cxp >= (int)gw || cyp < 0 || cyp >= (int)gh) return;
    uint dbits = as_uint(sz);
    ulong key = ((ulong)dbits << 32) | (ulong)i;
    atom_min(&cell[cyp * gw + cxp], key);  // nearest surfel in this cell
}

// Pass 2: one thread per PIXEL. Look in the pixel's cell + 8 neighbors for the
// surfel whose projection is nearest this pixel and nearest in depth; that is
// the surface the pixel's ray hits. Write its shaded color, or mark empty.
__kernel void shade_pixels(
    __global const Surfel* surfels,
    __global const ulong* cell,
    const uint gw, const uint gh, const uint cellpx,
    const float3 eye, const float3 fwd, const float3 right, const float3 up,
    const float focal, const uint W, const uint H,
    const float3 light_dir,
    __global uchar4* img, __global float* depth)
{
    uint x = get_global_id(0), y = get_global_id(1);
    if (x >= W || y >= H) return;
    uint pidx = y * W + x;
    int cxp = x / cellpx, cyp = y / cellpx;
    float bestd2 = 1e30f, bestz = 1e30f;
    int best = -1;
    for (int dy = -1; dy <= 1; ++dy)
    for (int dx = -1; dx <= 1; ++dx) {
        int gx = cxp + dx, gy = cyp + dy;
        if (gx < 0 || gx >= (int)gw || gy < 0 || gy >= (int)gh) continue;
        ulong key = cell[gy * gw + gx];
        if (key == 0xFFFFFFFFFFFFFFFFUL) continue;
        uint i = (uint)(key & 0xFFFFFFFFUL);
        float sx, sy, sz;
        if (!project(&surfels[i], eye, fwd, right, up, focal, W, H, &sx, &sy, &sz))
            continue;
        float ddx = sx - (x + 0.5f), ddy = sy - (y + 0.5f);
        float d2 = ddx*ddx + ddy*ddy;
        // nearest in screen space, tie-broken by depth
        if (d2 < bestd2 || (d2 == bestd2 && sz < bestz)) {
            bestd2 = d2; bestz = sz; best = (int)i;
        }
    }
    if (best < 0 || bestd2 > (float)(cellpx*cellpx*4)) {
        img[pidx] = (uchar4)(0,0,0,0);   // empty -> hole (alpha 0)
        depth[pidx] = 1e30f;
        return;
    }
    Surfel s = surfels[best];
    float3 nrm = (float3)(s.nx, s.ny, s.nz);
    float lam = clamp(dot(nrm, light_dir), 0.0f, 1.0f) * 0.25f + 0.75f;
    uchar r = (uchar)(clamp(s.r*lam,0.0f,1.0f)*255.0f);
    uchar g = (uchar)(clamp(s.g*lam,0.0f,1.0f)*255.0f);
    uchar b = (uchar)(clamp(s.b*lam,0.0f,1.0f)*255.0f);
    img[pidx] = (uchar4)(r,g,b,255);
    depth[pidx] = bestz;
}

// Pass 3: fill genuine holes (alpha 0) that are surrounded by surface, by
// copying the nearest filled neighbor (no averaging cream+black -> no grey).
__kernel void fill_holes(
    __global uchar4* img, const uint W, const uint H,
    __global const uchar4* src)
{
    uint x = get_global_id(0), y = get_global_id(1);
    if (x >= W || y >= H) return;
    uint pidx = y * W + x;
    if (src[pidx].w != 0) { img[pidx] = src[pidx]; return; }  // already filled
    // look for nearest filled among 8 neighbors; take the closest one
    int found = 0; uchar4 best = (uchar4)(15,15,18,255);
    for (int dy = -1; dy <= 1 && !found; ++dy)
    for (int dx = -1; dx <= 1; ++dx) {
        if (dx==0 && dy==0) continue;
        int X = (int)x+dx, Y = (int)y+dy;
        if (X<0||X>=(int)W||Y<0||Y>=(int)H) continue;
        uchar4 nb = src[Y*W+X];
        if (nb.w != 0) { best = nb; found = 1; break; }
    }
    img[pidx] = found ? (uchar4)(best.x,best.y,best.z,255)
                      : (uchar4)(15,15,18,255);
}

